(function dublinTracerouteHtmlViz(stdout, el) {
  const text = String(stdout || "");
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end <= start) {
    throw new Error("no JSON object in traceroute output");
  }
  const data = JSON.parse(text.slice(start, end + 1));
  const flowsObj = data.flows || {};
  const flowIds = Object.keys(flowsObj);
  if (!flowIds.length) {
    el.innerHTML = "<p class=\"viz-error\">No flows in traceroute result</p>";
    return;
  }

  function hopsOf(flow) {
    if (Array.isArray(flow)) return flow;
    if (flow && Array.isArray(flow.hops)) return flow.hops;
    return [];
  }

  function hopIp(hop) {
    if (!hop) return null;
    if (hop.received && hop.received.ip && hop.received.ip.src) {
      return String(hop.received.ip.src);
    }
    if (hop.name) return String(hop.name);
    return null;
  }

  function hopTtl(hop, idx) {
    const t = hop && hop.sent && hop.sent.ip && hop.sent.ip.ttl;
    return t != null ? Number(t) : idx + 1;
  }

  const NS = "http://www.w3.org/2000/svg";
  const boxW = 168;
  const boxH = 40;
  const colW = 220;
  const rowH = 72;
  const padX = 48;
  const padY = 44;
  /** @type {Map<string, {id: string, ip: string, ttl: number, x: number, y: number, rtts: number[]}>} */
  const nodes = new Map();
  /** @type {Array<{a: string, b: string, flow: string}>} */
  const edges = [];
  let maxTtl = 1;
  let maxCols = 1;

  for (const fid of flowIds) {
    const hops = hopsOf(flowsObj[fid]);
    let prevId = null;
    for (let i = 0; i < hops.length; i++) {
      const hop = hops[i];
      const ttl = hopTtl(hop, i);
      const ip = hopIp(hop) || `* (ttl ${ttl})`;
      const id = `${ttl}|${ip}`;
      if (!nodes.has(id)) {
        nodes.set(id, {
          id,
          ip,
          ttl,
          x: 0,
          y: 0,
          rtts: [],
        });
      }
      const n = nodes.get(id);
      if (hop.rtt_usec != null && Number.isFinite(Number(hop.rtt_usec))) {
        n.rtts.push(Number(hop.rtt_usec));
      }
      if (prevId) edges.push({ a: prevId, b: id, flow: fid });
      prevId = id;
      if (ttl > maxTtl) maxTtl = ttl;
    }
  }

  /** Group nodes by TTL for column layout. */
  const byTtl = new Map();
  for (const n of nodes.values()) {
    if (!byTtl.has(n.ttl)) byTtl.set(n.ttl, []);
    byTtl.get(n.ttl).push(n);
  }
  for (const [, list] of byTtl) {
    if (list.length > maxCols) maxCols = list.length;
    list.sort((a, b) => a.ip.localeCompare(b.ip));
    list.forEach((n, i) => {
      n.x = padX + (n.ttl - 1) * colW;
      n.y = padY + i * rowH;
    });
  }

  const width = padX * 2 + Math.max(1, maxTtl) * colW;
  const height = padY * 2 + Math.max(1, maxCols) * rowH;
  const svg = document.createElementNS(NS, "svg");
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  // Fit inside the viewport (header + padding reserved) — never force a scrollbar.
  const maxDispW = Math.max(320, Math.floor(window.innerWidth * 0.72));
  const maxDispH = Math.max(200, Math.floor(window.innerHeight * 0.55));
  const scale = Math.min(maxDispW / width, maxDispH / height);
  svg.setAttribute("width", String(Math.max(1, Math.round(width * scale))));
  svg.setAttribute("height", String(Math.max(1, Math.round(height * scale))));
  svg.setAttribute("preserveAspectRatio", "xMidYMid meet");

  const palette = ["#5b8def", "#3ecf8e", "#f0b429", "#e36bae", "#9b8cff"];
  const flowColor = new Map();
  flowIds.forEach((fid, i) => flowColor.set(fid, palette[i % palette.length]));

  for (const e of edges) {
    const a = nodes.get(e.a);
    const b = nodes.get(e.b);
    if (!a || !b) continue;
    const line = document.createElementNS(NS, "line");
