(function dublinTracerouteHtmlViz(stdout, el) {
  const text = String(stdout || "");
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end <= start) {
    throw new Error("no JSON object in traceroute output");
  }
  const data = JSON.parse(text.slice(start, end + 1));
  const flowsObj = data.flows || {};
  const flowIds = Object.keys(flowsObj);
  if (!flowIds.length) {
    el.innerHTML = "<p class=\"viz-error\">No flows in traceroute result</p>";
    return;
  }

  function hopsOf(flow) {
    if (Array.isArray(flow)) return flow;
    if (flow && Array.isArray(flow.hops)) return flow.hops;
    return [];
  }

  function hopIp(hop) {
    if (!hop) return null;
    if (hop.received && hop.received.ip && hop.received.ip.src) {
      return String(hop.received.ip.src);
    }
    if (hop.name) return String(hop.name);
    return null;
  }

  function hopTtl(hop, idx) {
    const t = hop && hop.sent && hop.sent.ip && hop.sent.ip.ttl;
    return t != null ? Number(t) : idx + 1;
  }

  const NS = "http://www.w3.org/2000/svg";
  const boxW = 168;
  const boxH = 40;
  const colW = 220;
  const rowH = 72;
  const padX = 48;
  const padY = 44;
  /** @type {Map<string, {id: string, ip: string, ttl: number, x: number, y: number, rtts: number[]}>} */
  const nodes = new Map();
