  const edges = [];
  let maxTtl = 1;
  let maxCols = 1;

  for (const fid of flowIds) {
    const hops = hopsOf(flowsObj[fid]);
    let prevId = null;
    for (let i = 0; i < hops.length; i++) {
      const hop = hops[i];
      const ttl = hopTtl(hop, i);
      const ip = hopIp(hop) || `* (ttl ${ttl})`;
      const id = `${ttl}|${ip}`;
      if (!nodes.has(id)) {
        nodes.set(id, {
          id,
          ip,
          ttl,
          x: 0,
          y: 0,
          rtts: [],
        });
      }
      const n = nodes.get(id);
      if (hop.rtt_usec != null && Number.isFinite(Number(hop.rtt_usec))) {
